exercises.starter:
pub mod net {
    pub struct Port {
        n: u16,
    }

    impl Port {
        pub fn new(n: u16) -> Option<Port> {
            if n == 0 { None } else { Some(Port { n }) }
        }

        pub fn get(&self) -> u16 {
            self.n
        }
    }
}

pub fn run() -> (u16, bool) {
    let p = net::Port { n: 8080 };
    (p.get(), net::Port::new(0).is_none())
}

exercises.tests:
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn builds_through_the_constructor() {
        assert_eq!(run(), (8080, true));
    }
}

exercises.solution:
